// CSD_RATIONALE_BEGIN
// This strategy tracks the full generated output, whether generation is currently
// inside a constrained arithmetic span, and the current constrained substring
// between << and >>. Outside constrained spans it generates freely so the model
// can write normal step-by-step explanations. When it emits "<<", the strategy
// switches into constrained mode and only allows parser-valid arithmetic tokens.
// Inside constrained mode, if the constrained prefix is already complete, it
// closes the span with >>. Otherwise it uses a constrained decoding helper,
// biased against repeating tokens from the current answer, and appends the token
// only when it is parser-valid. If decoding reaches a dead end, it rolls back to
// a valid constrained prefix. This state supports valid generation by ensuring
// constrained content always remains a parser-valid arithmetic expression while
// preserving the full answer text around those spans.
// CSD_RATIONALE_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant cost == 0
  invariant helpers.cost <= steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    var isComplete := parser.IsCompletePrefix(currentConstrainedOut);
    if isComplete {
      var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := closedGenerated;
      insideConstrainedOut := closedInside;
      currentConstrainedOut := closedCurrent;
      steps := steps + 1;
    } else {
      var deadEnd := helpers.DeadEndDetection(parser, currentConstrainedOut, 1);
      if deadEnd {
        var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
        var repairedGenerated, repairedCurrent := helpers.RollbackConstrainedSpan(
          parser, stablePrefix, generated, currentConstrainedOut
        );
        generated := repairedGenerated;
        currentConstrainedOut := repairedCurrent;
        steps := steps + 1;
        if !parser.IsValidPrefix(currentConstrainedOut) {
          insideConstrainedOut := false;
          currentConstrainedOut := [];
        }
      } else {
        var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next := helpers.RepetitionPenaltyStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, generated, 1.5, eosToken
        );
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
          if valid {
            var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
              lm, parser, generated, currentConstrainedOut, next
            );
            generated := appendedGenerated;
            insideConstrainedOut := appendedInside;
            currentConstrainedOut := appendedCurrent;
          } else {
            var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
            var repairedGenerated, repairedCurrent := helpers.RollbackConstrainedSpan(
              parser, stablePrefix, generated, currentConstrainedOut
            );
            generated := repairedGenerated;
            currentConstrainedOut := repairedCurrent;
            if !parser.IsValidPrefix(currentConstrainedOut) {
              insideConstrainedOut := false;
              currentConstrainedOut := [];
            }
